base.src/auth/session.py:
import hmac


def check_token(token, secret):
    return hmac.compare_digest(token, secret)

base.src/api.py:
from src.auth.session import check_token


def handle(request, secret):
    if not check_token(request.token, secret):
        return 401
    return 200

base.tests/test_session.py:
from src.auth.session import check_token


def test_accepts_matching_token():
    assert check_token("abc", "abc")


def test_rejects_other_token():
    assert not check_token("abc", "abd")

